#include <linux/platform_device.h>
#include <linux/gpio/driver.h>
#include <linux/io.h>
#include <linux/irq.h>
#include <linux/err.h>
#include <linux/slab.h>
#include <linux/module.h>

static int amd_gpio_probe(struct platform_device *pdev)
{
    struct gpio_chip *chip;
    struct resource *res;
    void __iomem *regs;
    int ret, irq;

    chip = devm_kzalloc(&pdev->dev, sizeof(*chip), GFP_KERNEL);
    if (!chip)
        return -ENOMEM;

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!res)
        return -ENODEV;

    regs = devm_ioremap_resource(&pdev->dev, res);
    if (IS_ERR(regs))
        return PTR_ERR(regs);

    irq = platform_get_irq(pdev, 0);
    if (irq < 0)
        return irq;

    spin_lock_init(&chip->lock);

    chip->label = "AMD_GPIO";
    chip->owner = THIS_MODULE;
    chip->base = -1;
    chip->ngpio = 32; /* Example value; adjust according to hardware */
    chip->can_sleep = false;
    chip->direction_input = NULL; /* Example hook */
    chip->direction_output = NULL; /* Example hook */
    chip->get = NULL; /* Example hook */
    chip->set = NULL; /* Example hook */
    chip->request = NULL;
    chip->free = NULL;

    ret = devm_gpiochip_add_data(&pdev->dev, chip, NULL);
    if (ret) {
        dev_err(&pdev->dev, "Failed to add GPIO chip\n");
        return ret;
    }

    ret = devm_request_irq(&pdev->dev, irq, NULL, 0, "AMD_GPIO_IRQ", NULL);
    if (ret) {
        dev_err(&pdev->dev, "Failed to request IRQ\n");
        return ret;
    }

    platform_set_drvdata(pdev, chip);
    dev_info(&pdev->dev, "AMD GPIO driver loaded successfully\n");

    return 0;
}

#include <linux/platform_device.h>
#include <linux/gpio.h>
#include <linux/slab.h>
#include <linux/io.h>
#include <linux/irq.h>
#include <linux/err.h>
#include <linux/device.h>
#include <linux/module.h>

int amdgpio_init(struct platform_device *pdev)
{
    struct gpio_chip *gpio_chip;
    struct resource *res;
    void __iomem *regs;
    int irq, ret;

    gpio_chip = kzalloc(sizeof(*gpio_chip), GFP_KERNEL);
    if (!gpio_chip)
        return -ENOMEM;

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!res) {
        ret = -ENODEV;
        goto err_free_gpio;
    }

    regs = devm_ioremap_resource(&pdev->dev, res);
    if (IS_ERR(regs)) {
        ret = PTR_ERR(regs);
        goto err_free_gpio;
    }

    irq = platform_get_irq(pdev, 0);
    if (irq < 0) {
        ret = irq;
        goto err_free_gpio;
    }

    gpio_chip->label = "amdgpio";
    gpio_chip->owner = THIS_MODULE;
    gpio_chip->direction_input = amdgpio_direction_input;
    gpio_chip->direction_output = amdgpio_direction_output;
    gpio_chip->get = amdgpio_get_value;
    gpio_chip->set = amdgpio_set_value;
    gpio_chip->debounce = amdgpio_set_debounce;
    gpio_chip->base = -1;
    gpio_chip->can_sleep = false;
    gpio_chip->ngpio = 32; /* Example number of GPIOs, adjust as needed */
    gpio_chip->of_gpio_n_cells = 2;

    ret = gpiochip_add_data(gpio_chip, NULL);
    if (ret) {
        dev_err(&pdev->dev, "Failed to register GPIO chip\n");
        goto err_free_gpio;
    }

    ret = devm_gpiochip_add_pin_range(&pdev->dev, gpio_chip, 0, 0, 32);
    if (ret) {
        dev_err(&pdev->dev, "Failed to add GPIO pin range\n");
        goto err_unregister_chip;
    }

    ret = devm_request_irq(&pdev->dev, irq, amdgpio_irq_handler,
                           IRQF_SHARED, "amdgpio", gpio_chip);
    if (ret) {
        dev_err(&pdev->dev, "Failed to request IRQ\n");
        goto err_unregister_chip;
    }

    dev_info(&pdev->dev, "AMD GPIO driver loaded successfully\n");
    return 0;

err_unregister_chip:
    gpiochip_remove(gpio_chip);
err_free_gpio:
    kfree(gpio_chip);
    return ret;
}

